SELECT id AS bankAccountId, bank_code AS bankCode, CONCAT( REPEAT('*', GREATEST(CHAR_LENGTH(mock_account_number) - 4, 0)), RIGHT(mock_account_number, 4) ) AS maskedAccountNumber, currency AS currency, balance AS balance, available_amount AS availableAmount, status AS status FROM mock_bank_accounts WHERE user_id = #{userId}
AND status = #{status}
ORDER BY id
